var SAFE_CODE = /^(?:HEKTOR|SFTP|XML|ZIP|MEDIA|EXPORT|SOURCE|LOCK|SYNC|INVALID|OUT_OF_ORDER|SNAPSHOT|STALE|FUTURE)_[A-Z0-9_]+$/;
